import { LocalPlant } from './plant-database';

/** Compact plant entry: [id, name, sciName, family, type, cycle, watering, sunlight, careLevel, growthRate, indoor, medicinal, edible, flowers, floweringSeason, regions, imageUrl, images, description] */
type CompactPlant = [string, string, string, string, string, string, string, string[], string, string, boolean, boolean, boolean, boolean, string | null, string[], string, string[], string];

function expand(p: CompactPlant): LocalPlant {
  return {
    id: `local-${p[0]}`,
    common_name: p[1],
    scientific_name: [p[2]],
    other_names: {},
    family: p[3],
    type: p[4],
    cycle: p[5],
    watering: p[6],
    sunlight: p[7],
    care_level: p[8],
    growth_rate: p[9],
    indoor: p[10],
    medicinal: p[11],
    edible: p[12],
    flowers: p[13],
    flowering_season: p[14],
    regions: p[15],
    image_url: p[16],
    images: p[17],
    description: p[18],
    origin: p[15],
  };
}

